// ══════════════════════════════════ AUTH / LOGIN ══════════════════════════════════
// Real auth: netlify/functions/auth.js verifies credentials server-side and sets a
// signed, HttpOnly session cookie. netlify/functions/sheet-store.js verifies that
// cookie on every request and rejects anything without a valid session — the login
// screen is a real gate now, not just a UI hint.

let currentUser = null;

async function attemptLogin(){
  const submitBtn = document.getElementById('login-submit-btn');
  if(submitBtn && submitBtn.disabled) return;

  const uEl = document.getElementById('login-username');
  const pEl = document.getElementById('login-password');
  const errEl = document.getElementById('login-error');

  const u = (uEl.value || '').trim();
  const p = pEl.value || '';

  // Clear previous error
  errEl.textContent = '';

  if(!u || !p){
    errEl.textContent = 'Please enter username and password.';
    return;
  }

  if(submitBtn) submitBtn.disabled = true;

  try {
    const res = await fetch('/.netlify/functions/auth', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      credentials: 'include',
      body: JSON.stringify({
        username: u,
        password: p
      })
    });

    const result = await res.json();

    if(!res.ok){
      errEl.textContent = result.error || 'Invalid username or password.';
      if(submitBtn) submitBtn.disabled = false;
      return;
    }

    currentUser = {
      username: result.username,
      role: result.role,
      displayName: result.displayName || result.username
    };

    await enterApp();

  } catch(error) {
    console.error('Login error:', error);
    errEl.textContent = 'Unable to connect to the login server. Please try again.';
  } finally {
    if(submitBtn) submitBtn.disabled = false;
  }
}

async function logoutUser(){
  currentUser = null;
  // Clear the server-side session cookie so it can't be reused after logout.
  try{
    await fetch('/.netlify/functions/logout', { method: 'POST', credentials: 'include' });
  }catch(e){
    console.warn('Logout request failed (cookie may still be valid until it expires):', e);
  }
  // Wipe sensitive data from memory too, not just from the screen.
  cabins = buildDefaultCabins();
  occupants = [];
  payments = [];
  invoices = [];
  leads = [];
  quotations = [];
  virtualOffice = [];
  documents = defaultDocuments();
  appSettings = Object.assign({}, DEFAULT_SETTINGS);
  document.getElementById('login-screen').classList.remove('hidden');
  document.getElementById('login-username').value = '';
  document.getElementById('login-password').value = '';
  document.getElementById('login-error').textContent = '';
  document.getElementById('login-username').focus();
}

async function enterApp(){
  document.getElementById('login-screen').classList.add('hidden');
  document.getElementById('sf-username').textContent = currentUser.displayName;
  const badge = document.getElementById('sf-role-badge');
  badge.textContent = currentUser.role === 'admin' ? 'ADMIN' : 'STAFF';
  badge.className = 'role-badge ' + (currentUser.role === 'admin' ? 'admin' : 'staff');
  applyRolePermissions();
  // The pre-login sync (see INIT at the bottom of this file) ran without a session
  // cookie, so sheet-store.js rejected it and every table came back empty. Now that
  // we have a valid session, pull the real data. syncAllFromSheets() calls
  // refreshAll() itself once the data lands, so we don't need to call it separately.
  if(typeof syncAllFromSheets === 'function') await syncAllFromSheets();
  else if(typeof refreshAll === 'function') refreshAll();
}

function applyRolePermissions(){
  const isAdmin = currentUser && currentUser.role === 'admin';
  document.querySelectorAll('.admin-only-nav').forEach(el=>{
    el.classList.toggle('staff-only-hide', !isAdmin);
  });
  // If a staff user is somehow on a restricted page, bounce them to the dashboard.
  if(!isAdmin){
    const restricted = ['revenue','datasync'];
    const activePage = document.querySelector('.page.active');
    if(activePage && restricted.includes(activePage.id.replace('page-',''))){
      showPage('dashboard', document.querySelector('.nav-item'));
    }
  }
}

function checkAuthOnLoad(){
  // Login is never remembered across page loads — always start at the login screen.
  currentUser = null;
  document.getElementById('login-screen').classList.remove('hidden');
}

// ══════════════════════════════════ DATA MODEL ══════════════════════════════════
const RATE_PER_SEAT = 8000; // Default reference rate (₹ + GST per seat). Individual occupant rent remains editable and is never overwritten by this default.
const PARKING_RATE = 5000;
const FLOORS = ['First Floor','Second Floor','Third Floor'];

function genRegularFloor(prefix, cprefix){
  const seats = [6,3,3,3,3,5,5,2,10,10,10,10];
  const arr = seats.map((s,i)=>({id:prefix+(i+1), seater:s}));
  for(let i=1;i<=6;i++) arr.push({id:cprefix+i, seater:1});
  return arr;
}
const FLOOR_LAYOUT = {
  'First Floor': [
    {id:'F1', seater:5},
    {id:'F2/F3', seater:7, note:'Merged conference-style cabin'},
    {id:'F4', seater:3},
    {id:'F5', seater:3},
    {id:'F6', seater:2},
    {id:'F7', seater:10},
    {id:'F8', seater:10},
    {id:'F9', seater:10},
    {id:'FC1', seater:1},{id:'FC2', seater:1},{id:'FC3', seater:1},{id:'FC4', seater:1},
    {id:'FC5', seater:1},{id:'FC6', seater:1},{id:'FC7', seater:1},{id:'FC8', seater:1},
    {id:'FC9', seater:1},{id:'FC10', seater:1},{id:'FC11', seater:1},
  ],
  'Second Floor': genRegularFloor('S','SC'),
  'Third Floor': genRegularFloor('T','TC'),
};
const SEED_OCCUPIED = [];

function buildDefaultCabins(){
  const cabins = [];
  FLOORS.forEach(floor=>{
    FLOOR_LAYOUT[floor].forEach((c,idx)=>{
      cabins.push({
        id: c.id, floor, seater: c.seater, sno: idx+1,
        occupied: SEED_OCCUPIED.includes(c.id),
        occupantId: null, occupantName: null,
        note: c.note || ''
      });
    });
  });
  return cabins;
}

// All persistent data now lives in Google Sheets only (no localStorage). These
// start as safe in-memory defaults and are overwritten by syncAllFromSheets()
// once the initial load from Sheets completes (see INIT at the bottom of this file).
let cabins = buildDefaultCabins();
let occupants = null;
let virtualOffice = [];
let documents = null;

const AGREEMENT_TEMPLATE_B64 = "";

function defaultDocuments(){
  return [{
    id:'doc-template', name:'COLLABOR8 Co-Working Space Agreement — Template.docx',
    category:'Template', mime:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    size: Math.round(AGREEMENT_TEMPLATE_B64.length*0.75),
    dataUrl:'data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,'+AGREEMENT_TEMPLATE_B64,
    uploaded: new Date().toISOString().slice(0,10), linkedOccupantId:null, notes:'Master blank agreement — Schedule A & B to be filled per client.'
  }];
}
// Pre-Sheets-load fallbacks — overwritten by syncAllFromSheets() once the real data arrives.
if (occupants === null) occupants = [];
if (documents === null) documents = defaultDocuments();

// Small key/value app settings (theme, payment link, UPI id, payee name) — persisted as a
// single-row "settings" tab in Google Sheets instead of localStorage.
const DEFAULT_SETTINGS = { theme:'dark', paymentLink:'', upiId:'', payeeName:'COLLABOR8' };
let appSettings = Object.assign({}, DEFAULT_SETTINGS);
function saveSettings(){ syncToSheet('settings', [appSettings]); }

// ══════════════════════════════════ GOOGLE SHEETS SYNC LAYER ══════════════════════════════════
// Google Sheets is now the ONLY persistent store — there is no localStorage anywhere in
// this app. Every save*() function below pushes a full copy of the array straight to the
// matching Google Sheets tab via a Netlify Function (credentials never touch the browser —
// see netlify/functions/sheet-store.js). On load, syncAllFromSheets() pulls every tab back
// down before the app is usable (see the INIT block at the bottom of this file).
//
// NOTE on `documents`: uploaded files are stored as base64 data URLs, which can exceed
// Google Sheets' ~50,000-character cell limit for large files. Each document is synced
// individually; any single document too large for a Sheets cell is kept in memory for the
// current session (so it still works today) but a warning is shown, since it will not
// survive a refresh unless you wire up real file storage (e.g. Google Drive) for it.
const SHEETS_CELL_LIMIT = 45000; // stay safely under Sheets' 50,000-char cell limit

const SHEETS_API = '/.netlify/functions/sheet-store';
let sheetsSyncEnabled = true; // flips to false automatically if the API isn't reachable

async function syncToSheet(tab, data){
  if(!sheetsSyncEnabled) return;
  try{
    const res = await fetch(SHEETS_API, {
      method:'POST',
      headers:{ 'Content-Type':'application/json' },
      body: JSON.stringify({ sheet: tab, data })
    });
    if(!res.ok) throw new Error('sync failed: ' + res.status);
  }catch(e){
    console.warn('Google Sheets sync failed for "'+tab+'" — this change may not be saved.', e);
  }
}

async function loadFromSheet(tab){
  try{
    const res = await fetch(SHEETS_API + '?sheet=' + encodeURIComponent(tab));
    if(!res.ok) throw new Error('load failed: ' + res.status);
    const body = await res.json();
    return Array.isArray(body.data) ? body.data : null;
  }catch(e){
    console.warn('Google Sheets load failed for "'+tab+'".', e);
    return null;
  }
}

// Pulls every table from Sheets and replaces the in-memory copy with it. Runs once
// right after a successful login (see enterApp() in the AUTH section above), since
// sheet-store.js now requires a valid session before it will return any data. Safe
// to call again any time (e.g. wire a "Sync now" button to it).
async function syncAllFromSheets(){
  const [c, o, p, inv, l, q, vo, d, s] = await Promise.all([
    loadFromSheet('cabins'), loadFromSheet('occupants'), loadFromSheet('payments'),
    loadFromSheet('invoices'), loadFromSheet('leads'), loadFromSheet('quotations'),
    loadFromSheet('virtual_office'), loadFromSheet('documents'), loadFromSheet('settings')
  ]);
  if(c && c.length) cabins = c;
  occupants = (o && o.length) ? o : [];
  if(p && p.length) payments = p;
  if(inv && inv.length) invoices = inv;
  if(l && l.length) leads = l;
  if(q && q.length) quotations = q;
  if(vo && vo.length) virtualOffice = vo;
  documents = (d && d.length) ? d : defaultDocuments();
  appSettings = (s && s.length && s[0]) ? Object.assign({}, DEFAULT_SETTINGS, s[0]) : Object.assign({}, DEFAULT_SETTINGS);
  applyTheme(appSettings.theme || 'dark');
  if(typeof refreshAll === 'function') refreshAll();
}

function saveCabins(){ syncToSheet('cabins', cabins); }
function saveOccupants(){ syncToSheet('occupants', occupants); }
function saveVirtualOffice(){ syncToSheet('virtual_office', virtualOffice); }
function saveDocuments(){
  const oversized = documents.filter(d => d.dataUrl && d.dataUrl.length > SHEETS_CELL_LIMIT);
  const syncable = documents.filter(d => !d.dataUrl || d.dataUrl.length <= SHEETS_CELL_LIMIT);
  if(oversized.length){
    console.warn('Some documents are too large for a Google Sheets cell and will only persist for this browser session:', oversized.map(d=>d.name));
  }
  syncToSheet('documents', syncable);
}
